contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "insufficient balance");

        uint depositsBeforeWithdraw = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint depositsAfterWithdraw = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(address(c).balance == 0 && depositsAfterWithdraw == depositsBeforeWithdraw);
    }

    receive() external payable {}
}

