// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        uint256 depositsBeforeWithdraw;
        try c.depositsCount() returns (uint256 __r) { depositsBeforeWithdraw = __r; } catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint256 depositsAfterWithdraw;
        try c.depositsCount() returns (uint256 __r) { depositsAfterWithdraw = __r; } catch { return; }
        assertTrue(address(c).balance == 0 && depositsAfterWithdraw == depositsBeforeWithdraw);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
